update public.project_state_stage_requirements r set status=case when r.requirement_key='basic_identity' and nullif(trim(ps.name),'') is not null then 'satisfied'::public.readiness_state when r.requirement_key='initial_context' and (nullif(trim(ps.site_location),'') is not null or nullif(trim(ps.sector),'') is not null or nullif(trim(ps.source_context),'') is not null or nullif(trim(ps.summary),'') is not null) then 'satisfied'::public.readiness_state when r.requirement_key='next_step' and nullif(trim(ps.next_action),'') is not null then 'satisfied'::public.readiness_state else r.status end, updated_at=now() from public.project_states ps where ps.id=r.project_state_id and r.stage='opportunity';
